        {
          "type": "debt",
          "priority": "low",
          "timestamp": "2026-06-05T09:51:55Z",
          "note": "views/strategy.js: The renderStrategyList function calls renderList(repos) which is defined as an inner function. The naming is slightly inconsistent with the outer function (renderStrategyList vs renderList inner) — a minor readability debt, but does not affect correctness."
        }
      ]
    },
    {
      "type": "qa",
      "status": "FAIL",
      "started_at": "2026-06-05T09:52:26Z",
      "completed_at": "2026-06-05T09:55:52Z",
