344	/**
345	 * Removes a repository entry from the registry.
346	 *
347	 * This operation does NOT delete any project data, files, or directories —
348	 * it only removes the declaration from `.repositories.json`.
349	 *
350	 * Throws NOT_FOUND (404) if no entry with the given `repoId` exists.
351	 *
352	 * @param ledgerRoot - Absolute path to the centralized ledger root directory.
353	 * @param repoId     - The `id` field of the repository entry to remove.
354	 */
355	export async function handleDeleteRepo(
356	  ledgerRoot: string,
357	  repoId: string
358	): Promise<{ deleted: true }> {
359	  const registry = await loadRegistry(ledgerRoot);
360	  const index = registry.repositories.findIndex((e) => e.id === repoId);
361	  if (index === -1) {
362	    throw new ApiError('NOT_FOUND', `Repository not found: '${repoId}'.`);
363	  }
364	
365	  const updatedRepositories = registry.repositories.filter((e) => e.id !== repoId);
366	  await saveRegistry(ledgerRoot, { repositories: updatedRepositories });
367	  return { deleted: true };
